/**
 * ============================================================================
 * 視覺藝術作品署名與靈感宣告 (ATTRIBUTION & INSPIRATION DECLARATION)
 * ============================================================================
 * 作者 (Author / Code Adaptor): Uncler M
 * 靈感啟發來源 (Inspired By): aorbital - "Skin Regeneration皮肤再生/自修复"
 * 原始作品討論 (Original Note): http://xhslink.com/o/8ipmD7jlYDZ
 * 授權協議 (License): Creative Commons Attribution-NonCommercial-ShareAlike 4.0 (CC BY-NC-SA 4.0)
 * 
 * [說明 / Notice]
 * 本作品由 Uncler M 編寫與視聽化對應。演算法靈感取材自 aorbital 創作之「表皮細胞
 * Voronoi 拓撲、分裂與生物自癒力場」視覺概念。
 * 專為 4K MV Visual Integration Editor 專案打造。
 * ============================================================================
 */

let NUM_CELLS = 48;
let cellSites = [];
let timeT = 0;

let smoothedSubBass = 0.0;
let smoothedPercussive = 0.0;
let smoothedMid = 0.0;

setup = () => {
  p5.disableFriendlyErrors = true;
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1.0);
  ellipseMode(CENTER);

  // 初始化生物細胞核網格 (Voronoi Cell Nuclei)
  let cols = 8, rows = 6;
  let wStep = width / cols;
  let hStep = height / rows;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let rx = (c + 0.5) * wStep + random(-wStep * 0.3, wStep * 0.3);
      let ry = (r + 0.5) * hStep + random(-hStep * 0.3, hStep * 0.3);
      cellSites.push({
        x: rx, y: ry,
        targetX: rx, targetY: ry,
        vx: 0, vy: 0,
        radius: random(40, 85),
        pulsePhase: random(TWO_PI),
        health: 1.0
      });
    }
  }
};

draw = () => {
  // 1. 動態音訊信號平滑處理
  let rawSubBass = (typeof sub_bass !== 'undefined') ? sub_bass : (typeof sub_bass_ratio !== 'undefined' ? sub_bass_ratio : (mouseIsPressed ? 0.85 : 0.25));
  let rawPercussive = (typeof percussive !== 'undefined') ? percussive : (mouseIsPressed ? 0.9 : 0.1);
  let rawMid = (typeof mid !== 'undefined') ? mid : (typeof mid_ratio !== 'undefined' ? mid_ratio : 0.3);

  smoothedSubBass += (rawSubBass - smoothedSubBass) * 0.15;
  smoothedPercussive += (rawPercussive - smoothedPercussive) * 0.3;
  smoothedMid += (rawMid - smoothedMid) * 0.2;

  timeT += 0.01 + smoothedMid * 0.02;

  // 2. 有機生物膜背景
  background(220, 45, 6, 0.25);

  let currentHue = (typeof chord_hue !== 'undefined' && chord_hue > 0) ? chord_hue : 160;

  // 3. 重拍觸發「細胞撕裂與自癒爆發 (Cell Tear Shockwave)」
  if (smoothedPercussive > 0.65 && random() < 0.2) {
    let shockX = random(width * 0.2, width * 0.8);
    let shockY = random(height * 0.2, height * 0.8);

    for (let i = 0; i < cellSites.length; i++) {
      let site = cellSites[i];
      let d = dist(site.x, site.y, shockX, shockY);
      if (d < 350) {
        let force = (1.0 - d / 350) * (30.0 + smoothedPercussive * 50.0);
        let ang = atan2(site.y - shockY, site.x - shockX);
        site.vx += cos(ang) * force;
        site.vy += sin(ang) * force;
        site.health = 0.2; // 瞬時受損
      }
    }
  }

  // 4. 細胞彈性自癒與彈簧動力學 (Self-Healing Spring Dynamics)
  for (let i = 0; i < cellSites.length; i++) {
    let site = cellSites[i];

    // 自癒力彈簧恢復 (Restoring force to origin target)
    let springK = 0.08;
    let damping = 0.82;

    let fx = (site.targetX - site.x) * springK;
    let fy = (site.targetY - site.y) * springK;

    site.vx = (site.vx + fx) * damping;
    site.vy = (site.vy + fy) * damping;

    // 生物膜抖動
    let bioNoise = noise(site.x * 0.005, site.y * 0.005, timeT) * TWO_PI;
    site.vx += cos(bioNoise) * (0.4 + smoothedMid * 1.2);
    site.vy += sin(bioNoise) * (0.4 + smoothedMid * 1.2);

    site.x += site.vx;
    site.y += site.vy;

    // 自癒健康度漸進恢復
    site.health = min(1.0, site.health + 0.03);
  }

  // 5. 繪製動態 Voronoi 表皮細胞連線與邊界 (Voronoi Mesh Lines)
  strokeWeight(1.0 + smoothedSubBass * 3.0);

  for (let i = 0; i < cellSites.length; i++) {
    let s1 = cellSites[i];

    for (let j = i + 1; j < cellSites.length; j++) {
      let s2 = cellSites[j];
      let d = dist(s1.x, s1.y, s2.x, s2.y);
      let thresholdD = (s1.radius + s2.radius) * (1.2 + smoothedSubBass * 0.6);

      if (d < thresholdD) {
        let edgeAlpha = map(d, 0, thresholdD, 0.8, 0.0);
        let healthColor = lerp(currentHue, (currentHue + 120) % 360, s1.health * s2.health);

        // 繪製生物膜交界邊線
        stroke(healthColor, 75, 95, edgeAlpha * 0.7);

        // 彈性彎曲中點 (Bending Membrane Midpoint)
        let midX = (s1.x + s2.x) * 0.5 + sin(timeT * 2 + i) * 12.0 * smoothedMid;
        let midY = (s1.y + s2.y) * 0.5 + cos(timeT * 2 + j) * 12.0 * smoothedMid;

        line(s1.x, s1.y, midX, midY);
        line(midX, midY, s2.x, s2.y);
      }
    }
  }

  // 6. 繪製發光細胞核 (Bio-luminescent Nuclei)
  for (let i = 0; i < cellSites.length; i++) {
    let site = cellSites[i];
    let nSize = site.radius * (0.4 + smoothedSubBass * 0.5 + sin(timeT * 3 + site.pulsePhase) * 0.15);
    let nHue = (currentHue + site.health * 60) % 360;

    // 外圍螢光暈 (Bioluminescent Glow)
    noStroke();
    fill(nHue, 85, 100, 0.25 * site.health);
    ellipse(site.x, site.y, nSize * 2.2, nSize * 2.2);

    // 細胞核核心
    fill(nHue, 40, 100, 0.95);
    ellipse(site.x, site.y, nSize, nSize);
  }
};

